"use strict";exports.MOOD_COLOR={"开心":"#FFD93D","平静":"#6BCB77","疲惫":"#B5D4E8","焦虑":"#E8836B","难过":"#E8836B","嘴馋":"#FFB88C","低落":"#B5D4E8","想家":"#FFD93D","期待":"#FFD93D","满足":"#6BCB77","得意":"#FFB88C","害羞":"#E8836B"},exports.MOOD_EMOJI={"开心":"😊","平静":"😌","疲惫":"😔","焦虑":"😤","难过":"😢","嘴馋":"🤤","低落":"🌧️","想家":"❤️","期待":"🤩","满足":"🥰","得意":"😎","害羞":"😳"},exports.autoLayout=function(h,s,e=24){const{x:t,y:x,w:y,h:w}=s,n=[];if(h<=0)return[];if(1===h)n.push({x:t,y:x,w:y,h:w});else if(2===h){const h=(y-e)/2;n.push({x:t,y:x,w:h,h:w},{x:t+h+e,y:x,w:h,h:w})}else if(3===h){const h=.58*y,s=y-h-e,o=(w-e)/2;n.push({x:t,y:x,w:h,h:w},{x:t+h+e,y:x,w:s,h:o},{x:t+h+e,y:x+o+e,w:s,h:o})}else if(4===h){const h=(y-e)/2,s=(w-e)/2;n.push({x:t,y:x,w:h,h:s},{x:t+h+e,y:x,w:h,h:s},{x:t,y:x+s+e,w:h,h:s},{x:t+h+e,y:x+s+e,w:h,h:s})}else{const h=.52*w,s=(w-h-e)/2,o=(y-e)/2;n.push({x:t,y:x,w:y,h:h},{x:t,y:x+h+e,w:o,h:s},{x:t+o+e,y:x+h+e,w:o,h:s},{x:t,y:x+h+e+s+e,w:o,h:s},{x:t+o+e,y:x+h+e+s+e,w:o,h:s})}for(;n.length<h;)n.push({x:t,y:x,w:1,h:1});return n.slice(0,h)},exports.chunkPages=function(h,s=5){const e=[];for(let t=0;t<h.length;t+=s)e.push(h.slice(t,t+s));return e};
